from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
DDL = ROOT / 'backend' / 'database' / 'migrations' / '20260908_catalogo_ampliado_gobierno_core.sql'

def ddl():
    return DDL.read_text(encoding='utf-8')

def test_gate2_creates_only_approved_gobierno_tables():
    text = ddl()
    created = set(re.findall(r'CREATE TABLE dbo\.(Gobierno_[A-Za-z0-9_]+)', text, flags=re.I))
    expected = {
        'Gobierno_EmpresaConfiguracion','Gobierno_Persona','Gobierno_PersonaVinculo',
        'Gobierno_RolCorporativoCatalogo','Gobierno_PersonaEmpresaRol','Gobierno_TipoDocumento',
        'Gobierno_Documento','Gobierno_DocumentoVersion','Gobierno_DocumentoMovimiento',
        'Gobierno_AlertaRegla','Gobierno_AlertaEvento',
    }
    assert created == expected

def test_gate2_does_not_create_canonical_masters_or_parallel_engines():
    text = ddl().lower()
    forbidden = [
        'create table dbo.sistema_empresas', 'create table dbo.usuario_catalogo',
        'create table dbo.cliente_catalogo', 'create table dbo.proveedor_catalogo',
        'create table dbo.cliente_contactos', 'create table dbo.proveedor_contactos',
        'create table dbo.tareas_inventario', 'create table dbo.operativo_notificaciones_log',
        'create table dbo.sistema_tareas',
    ]
    for token in forbidden:
        assert token not in text

def test_person_link_is_typed_to_canonical_entities():
    text = ddl()
    required = [
        'REFERENCES dbo.Usuario_Catalogo(UsuarioID)',
        'REFERENCES dbo.Cliente_Catalogo(ClienteID)',
        'REFERENCES dbo.Proveedor_Catalogo(ProveedorID)',
        'REFERENCES dbo.Cliente_Contactos(ContactoClienteID)',
        'REFERENCES dbo.Proveedor_Contactos(ContactoID)',
        'CK_GobPV_UnDestino',
    ]
    for token in required:
        assert token in text

def test_gate2_is_idempotent_by_object_guards():
    text = ddl()
    for table in re.findall(r'CREATE TABLE dbo\.(Gobierno_[A-Za-z0-9_]+)', text, flags=re.I):
        assert f"OBJECT_ID('dbo.{table}','U') IS NULL" in text

def test_gate2_structure_file_contains_no_seed_or_business_dml():
    text = re.sub(r'/\*.*?\*/', ' ', ddl(), flags=re.S).lower()
    for token in (' merge ', ' insert ', ' update ', ' delete '):
        assert token not in f' {text} '

def test_alert_event_references_external_engines_without_creating_them():
    text = ddl()
    assert 'TareaReferencia VARCHAR(50) NULL' in text
    assert 'NotificacionReferencia VARCHAR(50) NULL' in text
    assert 'FOREIGN KEY(TareaReferencia)' not in text
    assert 'FOREIGN KEY(NotificacionReferencia)' not in text
